// ---------- 事件剧本（tick 为 2s 采样序号；负值 = 已注入首屏历史）----------
const INCIDENTS=[
  {id:'checkout.error_rate', start:-52, total:120, mag: 4.8},  // 载入时已处于严重态
  {id:'payment.queue_depth', start:-34, total: 90, mag: 300},  // 载入时处于警告态
  {id:'index.lag',           start:-22, total: 70, mag: 13},   // 载入时处于警告态
